    'rcpanel_faq_g2_a'            => 'A Reseller can create cPanel accounts. A Master Reseller can create Reseller accounts (who create cPanel accounts). An Alpha Reseller can create Master, Reseller, and cPanel accounts — forming a full multi-tier hierarchy.',
