    'ralpha_faq_g3_q'             => 'Who is Alpha Reseller for?',
    'ralpha_faq_g3_a'             => 'Alpha Reseller is ideal for hosting companies that want to offer reseller programs, large agencies managing partner networks, or businesses that need multi-tier white-label hosting under their brand.',
    'ralpha_faq_g4_q'             => 'Can I also create cPanel accounts directly?',
