    'ralpha_faq_t1_q'             => 'Does each tier get its own WHM?',
    'ralpha_faq_t1_a'             => 'Yes. You, your Masters, and your Resellers each get their own WHM interface to manage accounts at their level. End-users get cPanel.',
    'ralpha_faq_t2_q'             => 'Can I set resource limits per Master Reseller?',
    'ralpha_faq_t2_a'             => 'Absolutely. You define disk, bandwidth, and account limits for each Master package. Masters then distribute resources to their Resellers, who distribute to cPanel accounts.',
