    'ralpha_faq_t3_a'             => 'Yes — LiteSpeed, CloudLinux, Imunify360, NVMe SSDs, and 10 Gbit/s networking. The only difference is the management hierarchy and resource allocation.',
    'ralpha_faq_t4_q'             => 'Can I migrate from another provider?',
    'ralpha_faq_t4_a'             => 'Yes, we offer free migrations. Our team will transfer your entire hierarchy — Master, Reseller, and cPanel accounts — to our infrastructure.',
    'ralpha_faq_b1_q'             => 'Does the price increase on renewal?',
    'ralpha_faq_b1_a'             => 'No — same price on every renewal. No hidden fees or surprise increases.',
    'ralpha_faq_b2_q'             => 'Can I add more disk space?',
    'ralpha_faq_b2_a'             => 'Yes, additional disk is available at €0.15/GB. Add it during checkout or anytime from your client area.',
