    // ── General FAQ ──
    'faq_gen_q1'  => 'How long does it take to activate my order?',
    'faq_gen_a1'  => 'Orders are typically activated within 2 to 20 minutes. If your service is not activated within this time, please open a ticket.',
    'faq_gen_q2'  => 'How can I pay an invoice?',
    'faq_gen_a2'  => 'Invoices can be paid online through your client account using any of the accepted payment methods.',
    'faq_gen_q3'  => 'How do I cancel a service?',
    'faq_gen_a3'  => 'You can cancel any service from your client dashboard by selecting the service and clicking the cancel button. Note: Canceling a service does not automatically qualify for a refund.',
    'faq_gen_q4'  => 'Can I postpone my payment?',
    'faq_gen_a4'  => 'Yes, you can request a payment extension by contacting Sales support before your due date.',
    'faq_gen_q5'  => 'Does hosting include a control panel?',
    'faq_gen_a5'  => 'Yes, all our hosting plans include the latest version of cPanel, allowing you to manage your website, databases, emails, and more.',
    'faq_gen_q6'  => 'Can I get a refund for unused services?',
    'faq_gen_a6'  => 'Yes, refunds are available but subject to our <a href=":refund_url">Refund Policy</a>. We offer a 30-day money-back guarantee on hosting plans.',
    'faq_gen_q7'  => 'What security measures are in place?',
    'faq_gen_a7'  => 'Our hosting services include firewalls, DDoS protection, SSL certificates, Imunify360, and CloudLinux. We conduct regular security audits.',
    'faq_gen_q8'  => 'Where can I check my billing status?',
    'faq_gen_a8'  => 'You can view and download invoices anytime from your client account. We maintain full transparency — there are no hidden fees.',
    'faq_gen_q9'  => 'How can I upgrade or downgrade my hosting?',
    'faq_gen_a9'  => 'Go to the upgrade/downgrade section in your dashboard, or contact our sales department for assistance.',

    // ── Hosting FAQ ──
    'faq_hosting_q1'  => 'What is cPanel hosting?',
    'faq_hosting_a1'  => 'cPanel hosting provides a graphical interface for managing your web server. You can create email accounts, manage files, set up databases, install apps, and configure DNS — all from a single dashboard.',
    'faq_hosting_q2'  => 'Which web server do you use?',
    'faq_hosting_a2'  => 'All hosting plans run on LiteSpeed Enterprise web server with LSCache, delivering significantly faster page loads compared to Apache.',
    'faq_hosting_q3'  => 'Can I host multiple websites on one plan?',
    'faq_hosting_a3'  => 'Yes. All plans except the starter tier support addon domains, allowing you to host multiple websites under a single hosting account.',
    'faq_hosting_q4'  => 'Do you offer free website migration?',
    'faq_hosting_a4'  => 'Absolutely. Open a support ticket after purchasing your plan, provide your old host credentials, and our team will migrate everything — files, databases, emails — within 24 hours at no extra cost.',
    'faq_hosting_q5'  => 'Is SSL included for free?',
    'faq_hosting_a5'  => 'Yes. AutoSSL is enabled on all hosting accounts and automatically provisions and renews free SSL certificates for every domain.',
    'faq_hosting_q6'  => 'How are backups handled?',
    'faq_hosting_a6'  => 'We provide free daily automated backups via JetBackup. You can restore files, databases, emails, or your entire account with a single click from cPanel.',
    'faq_hosting_q7'  => 'What happens if I exceed my disk or bandwidth limits?',
    'faq_hosting_a7'  => 'You will receive a notification when you approach your limits. Your site will not go offline immediately — we\'ll give you time to upgrade or optimise. You can upgrade your plan at any time from the dashboard.',

    // ── VPS FAQ ──
    'faq_vps_q1'  => 'What is the difference between VPS and shared hosting?',
    'faq_vps_a1'  => 'A VPS gives you dedicated CPU, RAM, and storage resources with full root access. Shared hosting shares resources across multiple users. VPS is ideal for applications that require more control, performance, or custom software.',
    'faq_vps_q2'  => 'Do I get full root access?',
    'faq_vps_a2'  => 'Yes. All VPS/VDS plans include full root (Linux) or Administrator (Windows) access. You have complete control over your server environment.',
    'faq_vps_q3'  => 'What virtualization technology do you use?',
    'faq_vps_a3'  => 'We use KVM (Kernel-based Virtual Machine) virtualization, which provides true hardware isolation and guaranteed resources for each VPS instance.',
    'faq_vps_q4'  => 'Can I install any operating system?',
    'faq_vps_a4'  => 'Yes. We offer a wide selection of OS templates including Ubuntu, Debian, CentOS, AlmaLinux, Rocky Linux, and Windows Server. You can also mount a custom ISO.',
    'faq_vps_q5'  => 'Is DDoS protection included?',
    'faq_vps_a5'  => 'Yes. All VPS plans include enterprise-grade DDoS mitigation at no additional cost to keep your server protected against volumetric attacks.',
    'faq_vps_q6'  => 'Can I upgrade my VPS resources later?',
    'faq_vps_a6'  => 'Yes. You can scale your VPS plan up or down at any time from your client dashboard. Resource changes are applied within minutes.',

    // ── Cloud FAQ ──
    'faq_cloud_q1'  => 'How does cloud billing work?',
    'faq_cloud_a1'  => 'Cloud servers are billed hourly based on the resources allocated. You only pay for what you use. You can create and destroy instances at any time and billing stops immediately when you delete a server.',
    'faq_cloud_q2'  => 'Can I manage cloud servers via API?',
    'faq_cloud_a2'  => 'Yes. We provide a full REST API that lets you create, manage, resize, and destroy cloud instances programmatically. API documentation is available in your dashboard.',
    'faq_cloud_q3'  => 'What cloud server locations are available?',
    'faq_cloud_a3'  => 'Cloud servers are available in 20+ locations across Europe, Americas, Asia, and Oceania. You can deploy instances in multiple regions simultaneously.',
    'faq_cloud_q4'  => 'Can I take snapshots of my cloud server?',
    'faq_cloud_a4'  => 'Yes. You can create point-in-time snapshots of your cloud server and use them to restore or clone instances. Snapshots are stored independently of the server.',
    'faq_cloud_q5'  => 'Is there a minimum commitment period?',
    'faq_cloud_a5'  => 'No. Cloud servers have no minimum commitment. You can spin up an instance for a few hours and delete it — you only pay for the time used.',

    // ── Reseller FAQ ──
    'faq_reseller_q1'  => 'What is reseller hosting?',
    'faq_reseller_a1'  => 'Reseller hosting lets you create and sell cPanel hosting accounts under your own brand. You get WHM (Web Host Manager) access to manage all your clients\' accounts from one place.',
    'faq_reseller_q2'  => 'What is the difference between cPanel Reseller, Master Reseller, and Alpha Reseller?',
    'faq_reseller_a2'  => '<strong>cPanel Reseller</strong> creates and manages cPanel accounts. <strong>Master Reseller</strong> can also create Reseller accounts (2-tier). <strong>Alpha Reseller</strong> can create Master accounts too (3-tier hierarchy).',
    'faq_reseller_q3'  => 'Can I use my own branding?',
    'faq_reseller_a3'  => 'Yes. All reseller plans support full white-label branding. Your clients will see your company name — YottaSrc branding is completely hidden.',
    'faq_reseller_q4'  => 'How do I bill my own clients?',
    'faq_reseller_a4'  => 'You set your own pricing and billing cycle. Most resellers use WHMCS or Blesta for automated billing. We also offer a free WHMReseller plugin for WHM-based billing management.',
    'faq_reseller_q5'  => 'Is there a limit on how many accounts I can create?',
    'faq_reseller_a5'  => 'The number of accounts depends on your plan. Higher-tier plans offer more accounts and disk space. You can upgrade at any time as your business grows.',
    'faq_reseller_q6'  => 'What about VPS Reseller?',
    'faq_reseller_a6'  => 'VPS Reseller lets you sell VPS instances under your own brand using the SolusVM panel. You manage resources and create VPS containers for your clients with full white-label support.',

    // ── Windows & Licenses FAQ ──
    'faq_windows_q1'  => 'Are the Microsoft licenses genuine?',
    'faq_windows_a1'  => 'Yes. All Microsoft product keys we sell are genuine retail or volume licenses sourced from authorized distributors. They activate directly with Microsoft servers.',
    'faq_windows_q2'  => 'How do I receive my product key?',
    'faq_windows_a2'  => 'Product keys are delivered instantly to your client account after payment. You will also receive an email with your license key and activation instructions.',
    'faq_windows_q3'  => 'Do you offer Windows VPS?',
    'faq_windows_a3'  => 'Yes. We offer Windows VPS with pre-installed Windows Server editions and RDP access. Windows licenses are included in the VPS price — no extra license fee required.',
    'faq_windows_q4'  => 'Can I transfer my license to another device?',
    'faq_windows_a4'  => 'Retail keys can typically be transferred to a new device after deactivating on the old one. Volume/OEM keys are bound to the original hardware. Check the specific product for details.',
    'faq_windows_q5'  => 'What if my key doesn\'t activate?',
    'faq_windows_a5'  => 'If you encounter any activation issues, open a support ticket immediately. We will either resolve the issue or provide a replacement key at no extra cost.',

    // ── Payment FAQ ──
    'faq_payment_q1'  => 'What payment methods do you accept?',
    'faq_payment_a1'  => 'We accept credit/debit cards (Visa, Mastercard, AMEX), PayPal, cryptocurrency (BTC, ETH, USDT, and more), bank transfers, and several regional payment methods.',
    'faq_payment_q2'  => 'Do prices increase on renewal?',
    'faq_payment_a2'  => 'No. Unlike many hosting providers, our renewal price is the same as the initial purchase price. No surprise increases.',
    'faq_payment_q3'  => 'Do you offer a money-back guarantee?',
    'faq_payment_a3'  => 'Yes. We offer a 30-day money-back guarantee on all hosting and reseller plans. VPS and cloud services are non-refundable but can be cancelled at any time.',
    'faq_payment_q4'  => 'Can I pay with cryptocurrency?',
    'faq_payment_a4'  => 'Yes. We accept Bitcoin, Ethereum, USDT, Litecoin, and 50+ other cryptocurrencies via our integrated crypto payment gateway.',
    'faq_payment_q5'  => 'Is auto-pay available?',
    'faq_payment_a5'  => 'Yes. You can enable automatic payments from your client dashboard using a saved credit card or PayPal. This ensures your services are never interrupted.',

    // ── Affiliate FAQ ──
    'faq_aff_q1'  => 'How does the affiliate program work?',
    'faq_aff_a1'  => 'Share your unique referral link. When someone signs up and makes a purchase through your link, you earn a commission on every qualifying sale. It\'s free to join.',
    'faq_aff_q2'  => 'How much commission do I earn?',
    'faq_aff_a2'  => 'Commission rates vary by product. Hosting and reseller plans offer up to 30% recurring commission. VPS and cloud products offer flat-rate commissions per sale.',
    'faq_aff_q3'  => 'When do I get paid?',
    'faq_aff_a3'  => 'Payouts are processed monthly after a 30-day holding period. You can choose to receive payment via PayPal, bank transfer, or account credit.',
    'faq_aff_q4'  => 'Is there a minimum payout threshold?',
    'faq_aff_a4'  => 'Yes. The minimum payout threshold is $25. Once your balance reaches this amount, your earnings will be included in the next payout cycle.',
    'faq_aff_q5'  => 'Can I track my referrals?',
    'faq_aff_a5'  => 'Yes. Your affiliate dashboard shows real-time statistics including clicks, signups, conversions, and commission earnings.',

